{
  "name": "opencode-go-limits",
  "version": "0.2.0",
  "description": "OpenCode TUI sidebar widget: opencode Go subscription usage limits (session/weekly/monthly) as bars + percentages",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-go",
    "tui",
    "sidebar",
    "usage",
    "rate-limits",
    "quota",
    "subscription"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DanielNinov/opencode-go-limits.git"
  },
  "bugs": {
    "url": "https://github.com/DanielNinov/opencode-go-limits/issues"
  },
  "homepage": "https://github.com/DanielNinov/opencode-go-limits#readme",
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": "^1.3.4 || ^2.0.0"
  },
  "scripts": {
    "build": "node build.mjs",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0",
    "@opencode/plugin": ">=2.0.20",
    "@opentui/solid": ">=0.1.0",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": { "optional": true },
    "@opencode/plugin": { "optional": true },
    "@opentui/solid": { "optional": true },
    "solid-js": { "optional": true }
  },
  "devDependencies": {
    "@babel/cli": "^8.0.6",
    "@babel/core": "^8.0.7",
    "@babel/plugin-syntax-jsx": "^8.0.1",
    "@babel/preset-typescript": "^8.0.7",
    "@opencode-ai/plugin": "1.18.35",
    "@opencode/plugin": "2.0.24",
    "@opencode/theme": "2.0.24",
    "@opentui/solid": "0.1.107",
    "@types/node": "^24.10.9",
    "babel-preset-solid": "^1.9.16",
    "solid-js": "1.9.12",
    "typescript": "^5.9.3"
  }
}
